-- Six published human-risk modules: email, SMS, WhatsApp, voice, jobs, and mobile money.
-- Interactive artifacts live in scenario content JSON and are rendered by the frontend inspector.

create or replace function public._seed_practice_module(
  target_slug text,
  target_title jsonb,
  target_description jsonb,
  target_material jsonb,
  target_scenarios jsonb
) returns void language plpgsql as $$
declare
  module_id uuid;
  scenario_row jsonb;
  option_row jsonb;
  v_scenario_id uuid;
begin
  insert into public.training_modules (slug, title, description, learning_material, is_published, is_assessment)
  values (target_slug, target_title, target_description, target_material, true, false)
  on conflict (slug) do update
    set title = excluded.title,
        description = excluded.description,
        learning_material = excluded.learning_material,
        is_published = true,
        is_assessment = false
  returning id into module_id;

  for scenario_row in select value from jsonb_array_elements(target_scenarios)
  loop
    insert into public.scenarios (module_id, slug, content, risk_dimensions)
    values (
      module_id,
      scenario_row->>'slug',
      scenario_row->'content',
      array(select jsonb_array_elements_text(scenario_row->'risk_dimensions'))
    )
    on conflict (slug) where slug is not null
    do update
      set module_id = excluded.module_id,
          content = excluded.content,
          risk_dimensions = excluded.risk_dimensions
    returning id into v_scenario_id;

    for option_row in select value from jsonb_array_elements(scenario_row->'options')
    loop
      insert into public.scenario_options (scenario_id, option_key, content, is_correct, feedback)
      values (
        v_scenario_id,
        option_row->>'option_key',
        option_row->'content',
        (option_row->>'is_correct')::boolean,
        option_row->'feedback'
      )
      on conflict (scenario_id, option_key) do update
        set content = excluded.content,
            is_correct = excluded.is_correct,
            feedback = excluded.feedback;
    end loop;
  end loop;
end;
$$;

select public._seed_practice_module(
  'phishing-email-fundamentals',
  '{"en":"Phishing Email Fundamentals","af":"E-pos-uitvissinggrondbeginsels","pt":"Fundamentos de phishing por e-mail"}'::jsonb,
  '{"en":"Inspect sender, links, wording, QR codes, and attachments before you act on an email.","af":"Ondersoek die sender, skakels, bewoording, QR-kodes en aanhegsels voordat jy op ’n e-pos reageer.","pt":"Inspecione o remetente, os links, o texto, os códigos QR e os anexos antes de agir."}'::jsonb,
  '{
    "en":{"whyItMatters":"Email phishing works because a familiar name, perfect grammar, or a routine invoice can make a dangerous click feel ordinary. Spear phishing and AI-written messages are built to survive a quick glance.","warningSigns":"Lookalike domains, mismatched display names, unexpected attachments, QR codes that hide a destination, urgent account lockouts, and requests to sign in again.","bestPractice":"Pause. Inspect the sender address, hover every link, never enable macros, and report suspicious email through the official reporting channel. Open the real service from a known bookmark."},
    "af":{"whyItMatters":"E-pos-uitvissing werk omdat ’n bekende naam, perfekte grammatika of ’n gewone faktuur ’n gevaarlike klik gewoon kan laat lyk.","warningSigns":"Naboots-domeine, sendername wat nie klop nie, onverwagte aanhegsels, QR-kodes, dringende rekeningwaarskuwings en versoeke om weer aan te meld.","bestPractice":"Wag. Kontroleer die senderadres, hou die muis oor skakels, moenie makros aktiveer nie, en rapporteer verdagte e-pos via die amptelike kanaal."},
    "pt":{"whyItMatters":"O phishing por e-mail funciona porque um nome familiar, gramática perfeita ou uma fatura rotineira podem tornar um clique perigoso banal.","warningSigns":"Domínios semelhantes, nomes que não coincidem, anexos inesperados, códigos QR, bloqueios urgentes e pedidos para iniciar sessão novamente.","bestPractice":"Pare. Inspecione o endereço, passe o rato sobre os links, não ative macros e denuncie o e-mail pelo canal oficial."}
  }'::jsonb,
  '[
    {"slug":"email-spear-phishing-ceo","risk_dimensions":["Spear phishing","Authority","Urgency"],"content":{"en":{"title":"A highly personal request from the CEO","scenario":"Inspect this email. The display name matches your CEO, but the request is unusual. What should you do?","channel":"Email","interaction":"email","email":{"fromName":"Thandi Moyo, CEO","fromAddress":"thandi.moyo@marics-holdingss.example","to":"you@company.na","subject":"Need you on this before the board call — confidential","date":"Monday 08:07","body":"I know you handled the Windhoek supplier file last quarter. I am in a board prep session and cannot take calls. Please buy six Shoprite gift cards totaling N$9,000 and send the codes in a reply. Do not copy anyone. I will reimburse you this afternoon.","link":{"display":"I will explain after the meeting","actual":"mailto:thandi.moyo@marics-holdingss.example","safe":false}}}},
     "options":[
      {"option_key":"A","is_correct":false,"content":{"en":"Buy the cards immediately so the CEO is not delayed."},"feedback":{"en":{"choice":"Personal details and a familiar name do not prove identity.","explanation":"Spear phishing uses facts about your work to create trust. Gift-card codes are a classic untraceable payment."}}},
      {"option_key":"B","is_correct":true,"content":{"en":"Inspect the sender address, ignore the request, and verify through a known internal channel."},"feedback":{"en":{"choice":"You separated the display name from the actual address.","explanation":"The domain is a lookalike. Confirm unusual payment requests in person or on a number you already have."}}},
      {"option_key":"C","is_correct":false,"content":{"en":"Reply asking whether the amount can be reduced."},"feedback":{"en":{"choice":"Replying still engages the attacker.","explanation":"Any reply confirms that the mailbox is active. Verify independently instead."}}},
      {"option_key":"D","is_correct":false,"content":{"en":"Forward it to the whole team so someone else can decide."},"feedback":{"en":{"choice":"Forwarding spreads a live attack.","explanation":"Report it through the official channel rather than widening the audience."}}}
    ]},
    {"slug":"email-ai-perfect-grammar","risk_dimensions":["AI-generated phishing","Trust"],"content":{"en":{"title":"A perfectly written bank notice","scenario":"The email has no spelling mistakes and uses your full name. Inspect the sender and link.","channel":"Email","interaction":"email","email":{"fromName":"Bank Windhoek Security","fromAddress":"alerts@secure-bankwindhoek.example","to":"you@company.na","subject":"Action required: confirm a new device on your profile","date":"Today 11:42","body":"Dear colleague, we detected a new device signing in to internet banking. To keep your profile active, confirm this device within 20 minutes using the secure portal. Failure to confirm may pause debit orders.","link":{"display":"https://www.bankwindhoek.com.na/security","actual":"https://secure-bankwindhoek.example/login","safe":false}}}},
     "options":[
      {"option_key":"A","is_correct":false,"content":{"en":"Click the link because the grammar and branding look professional."},"feedback":{"en":{"choice":"AI can write flawless phishing.","explanation":"Perfect English is no longer a reliability signal. Compare the real destination with the official domain."}}},
      {"option_key":"B","is_correct":false,"content":{"en":"Sign in so debit orders are not paused."},"feedback":{"en":{"choice":"Urgency is the hook.","explanation":"Banks do not require you to confirm a device through an unexpected email link."}}},
      {"option_key":"C","is_correct":true,"content":{"en":"Close the email and open banking from the official app or a saved bookmark."},"feedback":{"en":{"choice":"You used a channel you already trust.","explanation":"The visible URL and the actual destination differ. Official apps and bookmarks avoid lookalike pages."}}},
      {"option_key":"D","is_correct":false,"content":{"en":"Call the phone number printed in the email."},"feedback":{"en":{"choice":"Contact details inside a suspicious message can be fake.","explanation":"Use the number on your card or in the official app."}}}
    ]},
    {"slug":"email-lookalike-login","risk_dimensions":["Lookalike domain","Credential theft"],"content":{"en":{"title":"A fake Microsoft login page","scenario":"A shared-file email leads to a login page. Inspect the link destination.","channel":"Email","interaction":"email","email":{"fromName":"Microsoft 365","fromAddress":"no-reply@micros0ftonline.example","to":"you@company.na","subject":"A file was shared with you: Q4 payroll.xlsx","body":"Your colleague shared a spreadsheet. Sign in to review it.","link":{"display":"https://microsoft.com/share","actual":"https://micros0ftonline.example/login","safe":false}}}},
     "options":[
      {"option_key":"A","is_correct":true,"content":{"en":"Do not enter credentials; open the real document library from a known work bookmark and report the email."},"feedback":{"en":{"choice":"You refused the lookalike page.","explanation":"The letter o was replaced with a zero. Fake login pages exist to capture passwords and MFA."}}},
      {"option_key":"B","is_correct":false,"content":{"en":"Sign in because you were expecting a payroll file."},"feedback":{"en":{"choice":"Expectation does not verify the destination.","explanation":"Open the official service directly and see whether a real share exists."}}},
      {"option_key":"C","is_correct":false,"content":{"en":"Enter a fake password to test the page."},"feedback":{"en":{"choice":"Interacting still confirms the mailbox is live.","explanation":"Close it and report it. Do not probe a phishing site with any password."}}},
      {"option_key":"D","is_correct":false,"content":{"en":"Save the link to inspect later from home."},"feedback":{"en":{"choice":"Keeping the link increases the chance of a later click.","explanation":"Report and delete. Use the official library instead."}}}
    ]},
    {"slug":"email-qr-quishing","risk_dimensions":["Quishing","Credential theft"],"content":{"en":{"title":"A QR code instead of a link","scenario":"Finance sends a payment QR code. Inspect what it hides.","channel":"Email","interaction":"email","email":{"fromName":"Finance Operations","fromAddress":"payments@company-finance.example","to":"you@company.na","subject":"Scan to approve today’s supplier batch","body":"The payment portal is busy. Scan this QR code with your phone to approve the batch before 16:00.","qr":{"label":"Approve supplier batch","destination":"https://company-finance.example/login"}}}},
     "options":[
      {"option_key":"A","is_correct":false,"content":{"en":"Scan it on your work phone because QR codes are safer than links."},"feedback":{"en":{"choice":"QR codes are just hidden links.","explanation":"Quishing hides a destination behind an image so you cannot hover it on a computer."}}},
      {"option_key":"B","is_correct":true,"content":{"en":"Do not scan it. Open the known finance system from the official bookmark and report the message."},"feedback":{"en":{"choice":"You avoided a hidden destination.","explanation":"Start from a system you already trust. Unexpected QR codes in email should be treated like unexpected links."}}},
      {"option_key":"C","is_correct":false,"content":{"en":"Ask a coworker to scan it first."},"feedback":{"en":{"choice":"That moves the risk onto someone else.","explanation":"Report the message instead of testing it on another device."}}},
      {"option_key":"D","is_correct":false,"content":{"en":"Scan it but do not enter a password."},"feedback":{"en":{"choice":"The page can still capture a session or prompt for MFA.","explanation":"Do not open unknown QR destinations at all."}}}
    ]},
    {"slug":"email-fake-invoice-attachment","risk_dimensions":["Attachments","Financial manipulation"],"content":{"en":{"title":"An overdue invoice with a strange file","scenario":"Inspect the attachment name and type before you open anything.","channel":"Email","interaction":"email","email":{"fromName":"Namibia Freight Solutions","fromAddress":"billing@namibiafreight-invoices.example","to":"accounts@company.na","subject":"OVERDUE: Invoice NFS-88421 — enable content to view","body":"Please find the overdue invoice attached. Enable macros if the spreadsheet appears blank. Payment is required today to avoid a collection listing.","attachment":{"name":"Invoice_NFS_88421.xlsm","type":"Excel macro-enabled workbook","note":"Unexpected macros can run code as soon as you enable content."}}}},
     "options":[
      {"option_key":"A","is_correct":true,"content":{"en":"Do not enable macros. Verify the invoice with the supplier contact already on file and report the email."},"feedback":{"en":{"choice":"You treated the file as untrusted.","explanation":"Fake invoices use urgency and macros. Confirm independently and use the official reporting button or security mailbox."}}},
      {"option_key":"B","is_correct":false,"content":{"en":"Enable content so you can see whether the invoice looks real."},"feedback":{"en":{"choice":"Enabling macros is the attacker’s goal.","explanation":"A blank spreadsheet is a common lure to make you turn protection off."}}},
      {"option_key":"C","is_correct":false,"content":{"en":"Forward the file to your personal email and open it there."},"feedback":{"en":{"choice":"That copies malware onto another account.","explanation":"Keep the file in place and report it."}}},
      {"option_key":"D","is_correct":false,"content":{"en":"Pay a small amount so collection is paused."},"feedback":{"en":{"choice":"Payment does not verify the invoice.","explanation":"Verify the debt through the known supplier process first."}}}
    ]},
    {"slug":"email-how-to-report","risk_dimensions":["Reporting","Safe practice"],"content":{"en":{"title":"How to report a suspicious email","scenario":"You have decided the email is suspicious. What is the correct reporting path?","channel":"Email","interaction":"email","email":{"fromName":"IT Helpdesk","fromAddress":"helpdesk@it-helpdesk-secure.example","to":"you@company.na","subject":"Mailbox storage full — confirm password","body":"Your mailbox is 99% full. Confirm your password here or mail will bounce.","link":{"display":"https://outlook.office.com","actual":"https://it-helpdesk-secure.example","safe":false}}}},
     "options":[
      {"option_key":"A","is_correct":false,"content":{"en":"Delete it quietly so nobody is embarrassed."},"feedback":{"en":{"choice":"Silent deletion hides an active campaign.","explanation":"Reporting helps defenders block the sender for everyone else."}}},
      {"option_key":"B","is_correct":false,"content":{"en":"Reply with STOP and ask them to remove you."},"feedback":{"en":{"choice":"Replies confirm the address is live.","explanation":"Use the report button or forward to the official security mailbox without extra conversation."}}},
      {"option_key":"C","is_correct":true,"content":{"en":"Use the email client’s Report phishing action or forward it to the official security address, then leave it unopened."},"feedback":{"en":{"choice":"You used the approved reporting path.","explanation":"Do not click, do not reply, and do not forward to friends. The report action preserves headers that help investigation."}}},
      {"option_key":"D","is_correct":false,"content":{"en":"Print it and leave it on the printer for IT."},"feedback":{"en":{"choice":"Printed copies lose technical headers.","explanation":"Digital reporting keeps the evidence defenders need."}}}
    ]}
  ]'::jsonb
);

select public._seed_practice_module(
  'sms-smishing-banking-scams',
  '{"en":"SMS Smishing and Banking Scams","af":"SMS-smishing en bankbedrog","pt":"Smishing por SMS e burlas bancárias"}'::jsonb,
  '{"en":"Investigate fake bank alerts, network messages, OTPs, prizes, deliveries, and follow-up calls.","af":"Ondersoek vals bankwaarskuwings, netwerkboodskappe, OTP’s, pryse, aflewerings en opvolgoproepe.","pt":"Investigue alertas bancários falsos, mensagens de rede, OTPs, prémios, entregas e chamadas de seguimento."}'::jsonb,
  '{
    "en":{"whyItMatters":"Smishing copies the short, trusted style of banks and mobile networks. A fake alert can steal an OTP or push you into a phone call with a scripted fraudster.","warningSigns":"Account suspension threats, prize claims, delivery fees, requests for OTPs, shortened links, and a call that continues the same story.","bestPractice":"Do not use numbers or links in the SMS. Open the official banking or courier app, or call the number on your card. Never read an OTP to anyone."},
    "af":{"whyItMatters":"Smishing boots die kort, vertroude styl van banke en selfoonnetwerke na.","warningSigns":"Dreigemente van rekeningopskorting, pryse, afleweringsfooie, OTP-versoeke, kort skakels en ’n oproep wat dieselfde storie voortsit.","bestPractice":"Moenie nommers of skakels in die SMS gebruik nie. Open die amptelike toep of bel die nommer op jou kaart. Deel nooit ’n OTP nie."},
    "pt":{"whyItMatters":"O smishing copia o estilo curto e confiável de bancos e redes móveis.","warningSigns":"Ameaças de suspensão, prémios, taxas de entrega, pedidos de OTP, links curtos e uma chamada que continua a história.","bestPractice":"Não use números ou links da SMS. Abra a aplicação oficial ou ligue para o número do cartão. Nunca leia um OTP."}
  }'::jsonb,
  '[
    {"slug":"sms-bank-suspension","risk_dimensions":["Smishing","Account restriction"],"content":{"en":{"title":"A fake bank suspension text","scenario":"Read this SMS thread and decide when it became unsafe.","channel":"SMS","interaction":"sms","sms":{"contact":"FNB Alerts","number":"+264 81 000 1111","messages":[{"from":"them","text":"FNB: Your account will be suspended in 30 minutes due to unusual activity.","time":"09:12"},{"from":"them","text":"Verify now: https://fnb-secure.example/unlock","time":"09:12","flagged":true}]}}},
     "options":[
      {"option_key":"A","is_correct":false,"content":{"en":"Open the link before the account is locked."},"feedback":{"en":{"choice":"The suspension deadline is the bait.","explanation":"Banks do not restore accounts through an SMS link."}}},
      {"option_key":"B","is_correct":true,"content":{"en":"Ignore the link and check the account in the official banking app or by calling the number on your card."},"feedback":{"en":{"choice":"You verified independently.","explanation":"The scam begins at the unverified link. Official apps bypass lookalike pages."}}},
      {"option_key":"C","is_correct":false,"content":{"en":"Reply YES to keep the account open."},"feedback":{"en":{"choice":"Replies confirm the number is active.","explanation":"Do not converse with an unverified alert."}}},
      {"option_key":"D","is_correct":false,"content":{"en":"Send your ID number so they can find the profile."},"feedback":{"en":{"choice":"Identity details are what the attacker wants.","explanation":"Never provide KYC data in reply to an unexpected SMS."}}}
    ]},
    {"slug":"sms-mobile-network","risk_dimensions":["Impersonation","Untrusted link"],"content":{"en":{"title":"A fraudulent mobile network message","scenario":"MTC appears to warn that your SIM will be deactivated.","channel":"SMS","interaction":"sms","sms":{"contact":"MTC","number":"1232","messages":[{"from":"them","text":"MTC NOTICE: Your SIM registration is incomplete. Update within 2 hours to avoid deactivation: https://mtc-sim.example","time":"14:03","flagged":true}]}}},
     "options":[
      {"option_key":"A","is_correct":true,"content":{"en":"Use the official MTC app, USSD, or a known store process instead of the SMS link."},"feedback":{"en":{"choice":"You used a channel you already trust.","explanation":"Network brands are copied constantly. Official apps and stores confirm SIM status."}}},
      {"option_key":"B","is_correct":false,"content":{"en":"Tap the link because the sender name shows MTC."},"feedback":{"en":{"choice":"Sender names on SMS can be spoofed.","explanation":"The short name is not cryptographic proof of the operator."}}},
      {"option_key":"C","is_correct":false,"content":{"en":"Send a copy of your ID to keep the number."},"feedback":{"en":{"choice":"That is identity theft in one step.","explanation":"Operators will not harvest ID documents from a surprise SMS."}}},
      {"option_key":"D","is_correct":false,"content":{"en":"Forward it to family so they can check it too."},"feedback":{"en":{"choice":"Forwarding spreads the lure.","explanation":"Report it and use official channels."}}}
    ]},
    {"slug":"sms-otp-theft","risk_dimensions":["OTP theft","Social engineering"],"content":{"en":{"title":"Someone asks for the SMS code","scenario":"A caller stays on the line while an OTP arrives.","channel":"SMS","interaction":"sms","sms":{"contact":"Bank OTP","number":"1200","messages":[{"from":"them","text":"Your FNB payment code is 481902. Do not share this code.","time":"10:41"},{"from":"you","text":"I did not start a payment.","time":"10:41"},{"from":"system","text":"The caller says: Read me the six digits so I can cancel the fraud.","flagged":true}]}}},
     "options":[
      {"option_key":"A","is_correct":false,"content":{"en":"Read the code so the bank can cancel the payment."},"feedback":{"en":{"choice":"The OTP is the key the attacker needs.","explanation":"Anyone who already has your password needs the OTP to finish the theft. Hang up."}}},
      {"option_key":"B","is_correct":true,"content":{"en":"Do not share the code. End the call and contact the bank using the number on your card."},"feedback":{"en":{"choice":"You kept the OTP private.","explanation":"Legitimate banks never ask you to read an SMS code to a caller."}}},
      {"option_key":"C","is_correct":false,"content":{"en":"Send a photo of the SMS instead of reading it."},"feedback":{"en":{"choice":"A photo is still the secret.","explanation":"Any disclosure of the OTP can approve a payment."}}},
      {"option_key":"D","is_correct":false,"content":{"en":"Give the first three digits only."},"feedback":{"en":{"choice":"Partial codes can still help an attacker.","explanation":"Share nothing from the message."}}}
    ]},
    {"slug":"sms-prize-and-delivery","risk_dimensions":["Unexpected reward","Delivery scam"],"content":{"en":{"title":"A prize and a parcel in one afternoon","scenario":"Two common SMS lures. Identify the safer habit.","channel":"SMS","interaction":"sms","sms":{"contact":"Rewards / NamPost","number":"+264 81 222 3344","messages":[{"from":"them","text":"PICK N PAY: You won N$2,000. Claim: https://pnp-win.example","time":"12:01","flagged":true},{"from":"them","text":"NAMPOST: Parcel held. Pay N$35 customs: https://nampost-pay.example","time":"12:18"}]}}},
     "options":[
      {"option_key":"A","is_correct":false,"content":{"en":"Claim the prize first, then pay the small customs fee."},"feedback":{"en":{"choice":"Both messages use the same trick.","explanation":"Unexpected money and unexpected fees are standard smishing."}}},
      {"option_key":"B","is_correct":true,"content":{"en":"Ignore both links. Check competitions and parcels only through official apps or known websites."},"feedback":{"en":{"choice":"You refused both unsolicited links.","explanation":"If a prize or parcel is real, it will appear in the official channel without this SMS."}}},
      {"option_key":"C","is_correct":false,"content":{"en":"Pay the customs fee because N$35 is a small risk."},"feedback":{"en":{"choice":"Small fees harvest cards.","explanation":"Card details entered on a fake page are then used for larger withdrawals."}}},
      {"option_key":"D","is_correct":false,"content":{"en":"Reply with your ID so they can verify the winner."},"feedback":{"en":{"choice":"That hands over KYC data.","explanation":"Real prizes are not claimed by SMS identity checks."}}}
    ]},
    {"slug":"sms-follow-up-call","risk_dimensions":["Follow-up call","Verification"],"content":{"en":{"title":"The SMS is followed by a phone call","scenario":"Find the moment the scam becomes a live conversation.","channel":"SMS","interaction":"sms","sms":{"contact":"Standard Bank","number":"+264 61 000 0000","messages":[{"from":"them","text":"STANDARD BANK: A payment of N$4,750 is pending. If this was not you, wait for our fraud desk to call.","time":"16:02"},{"from":"system","text":"One minute later your phone rings. The caller ID shows Standard Bank.","flagged":true}]}}},
     "options":[
      {"option_key":"A","is_correct":false,"content":{"en":"Answer and follow the caller’s instructions because the SMS said they would call."},"feedback":{"en":{"choice":"The SMS set up the call.","explanation":"Criminals send the text, then spoof the bank’s number."}}},
      {"option_key":"B","is_correct":true,"content":{"en":"Do not use the inbound call. Hang up and phone the bank using the number on your card."},"feedback":{"en":{"choice":"You broke the scripted sequence.","explanation":"Independent call-back is the verification step that smishing-plus-vishing cannot survive."}}},
      {"option_key":"C","is_correct":false,"content":{"en":"Ask the caller to email instead, using the address in the SMS."},"feedback":{"en":{"choice":"That stays inside the attacker’s channel.","explanation":"Switch to a contact method you already had printed or saved."}}},
      {"option_key":"D","is_correct":false,"content":{"en":"Stay on the line but refuse to give your PIN."},"feedback":{"en":{"choice":"The call itself is the unsafe channel.","explanation":"They may still request remote access or an OTP. Hang up."}}}
    ]},
    {"slug":"sms-conversation-turning-point","risk_dimensions":["Conversation analysis","Urgency"],"content":{"en":{"title":"Where does this SMS scam begin?","scenario":"A helpful chat turns into a request. Mark the unsafe turn.","channel":"SMS","interaction":"sms","sms":{"contact":"Lebo (new number)","number":"+264 81 765 4321","messages":[{"from":"them","text":"Hi, it’s Lebo from accounts. My phone died so I’m on this number today.","time":"08:50"},{"from":"you","text":"Got it, what do you need?","time":"08:51"},{"from":"them","text":"Please send the supplier OTP that just went to the office phone. Director is waiting.","time":"08:52","flagged":true}]}}},
     "options":[
      {"option_key":"A","is_correct":false,"content":{"en":"Send the OTP because you recognised the name Lebo."},"feedback":{"en":{"choice":"A new number plus an OTP request is the scam.","explanation":"The friendly introduction was only there to make the request feel internal."}}},
      {"option_key":"B","is_correct":false,"content":{"en":"Ask Lebo to voice-note the director’s surname first."},"feedback":{"en":{"choice":"The attacker already studied the company.","explanation":"Verify on the number you already have saved for Lebo."}}},
      {"option_key":"C","is_correct":true,"content":{"en":"Stop. Call or message Lebo on the number already in your contacts, and report the OTP request."},"feedback":{"en":{"choice":"You spotted the turning point.","explanation":"The scam begins when a new number asks for a verification code. Known contacts must be reached on known numbers."}}},
      {"option_key":"D","is_correct":false,"content":{"en":"Send the OTP in parts over several messages."},"feedback":{"en":{"choice":"The full code still arrives.","explanation":"Never share OTPs, even with people who sound like coworkers."}}}
    ]}
  ]'::jsonb
);

select public._seed_practice_module(
  'whatsapp-social-media-impersonation',
  '{"en":"WhatsApp and Social Media Impersonation","af":"WhatsApp- en sosiale media-nabootsing","pt":"WhatsApp e personificação nas redes sociais"}'::jsonb,
  '{"en":"Spot account takeovers, fake emergencies, impersonated managers, giveaways, romance and marketplace scams, and oversharing.","af":"Herken rekeningoorname, vals noodgevalle, nagebootste bestuurders, weggewings, romanse- en markplekbedrog, en oor-deling.","pt":"Identifique sequestro de contas, emergências falsas, gestores impersonados, sorteios, burlas românticas e de mercado, e excesso de partilha."}'::jsonb,
  '{
    "en":{"whyItMatters":"Messaging apps feel private and informal, so a hijacked display name or a family emergency can skip the checks people would apply to email.","warningSigns":"A new number, a request for secrecy or money, a manager who will not take a call, investment giveaways, and profiles that became romantic or commercial very quickly.","bestPractice":"Call the person on a number you already have. Turn on two-step verification. Limit who can see your status, photo, and last seen. Never send money, codes, or ID documents in-chat."},
    "af":{"whyItMatters":"Boodskaptoeps voel privaat, so ’n gekaapte naam of familiemoodgeval kan kontroles oorslaan.","warningSigns":"’n Nuwe nommer, geheimhouding of geldversoeke, ’n bestuurder wat nie wil praat nie, beleggingsweggewings en profiele wat vinnig romanties of kommersieel word.","bestPractice":"Bel die persoon op ’n nommer wat jy al het. Skakel twee-stap-verifikasie in. Beperk wie jou status sien. Moet nooit geld, kodes of ID in die kletse stuur nie."},
    "pt":{"whyItMatters":"As apps de mensagens parecem privadas, por isso um nome sequestrado ou uma emergência familiar pode saltar verificações.","warningSigns":"Número novo, pedidos de segredo ou dinheiro, um gestor que não atende, sorteios de investimento e perfis que ficam românticos ou comerciais depressa.","bestPractice":"Ligue para o número que já tem. Ative a verificação em dois passos. Limite quem vê o estado. Nunca envie dinheiro, códigos ou documentos no chat."}
  }'::jsonb,
  '[
    {"slug":"whatsapp-account-takeover","risk_dimensions":["Account takeover","Verification"],"content":{"en":{"title":"A WhatsApp account takeover","scenario":"Your colleague’s chat suddenly asks for a code. Choose replies, then decide.","channel":"WhatsApp","interaction":"whatsapp","chat":{"displayName":"Piet van Wyk","number":"+264 81 111 0000","verified":false,"start":"start","nodes":{"start":{"from":"them","text":"Hey, I lost access to WhatsApp. The app is asking for a code. Can you share the one that just came to the office phone?","choices":[{"label":"Send the code so they can get back in","next":"code"},{"label":"Call Piet on the saved number first","next":"safe"}]},"code":{"from":"system","text":"If you send that code, the attacker completes the takeover of Piet’s account.","end":true},"safe":{"from":"system","text":"Calling the saved number confirms whether Piet is really locked out. Real colleagues accept the check.","end":true}}}}},
     "options":[
      {"option_key":"A","is_correct":false,"content":{"en":"Send the SMS code so your colleague can recover the account."},"feedback":{"en":{"choice":"The recovery code is the takeover key.","explanation":"WhatsApp registration codes must never be shared, even with a familiar display name."}}},
      {"option_key":"B","is_correct":true,"content":{"en":"Do not send the code. Call or meet the person using a number already on file and report the attempt."},"feedback":{"en":{"choice":"You blocked the takeover.","explanation":"A hijacked or cloned chat will always sound like someone you know. Independent contact is the test."}}},
      {"option_key":"C","is_correct":false,"content":{"en":"Ask them to send a selfie in the same chat."},"feedback":{"en":{"choice":"A selfie can be stolen or deepfaked.","explanation":"Use a live call to a known number instead."}}},
      {"option_key":"D","is_correct":false,"content":{"en":"Tell them to turn off two-step verification."},"feedback":{"en":{"choice":"That makes takeover easier.","explanation":"Keep two-step verification on and never share codes."}}}
    ]},
    {"slug":"whatsapp-family-emergency","risk_dimensions":["Family emergency","Financial manipulation"],"content":{"en":{"title":"A fake family emergency","scenario":"The scammer will change story depending on how you reply.","channel":"WhatsApp","interaction":"whatsapp","chat":{"displayName":"Mom","number":"+264 81 555 0199","verified":false,"start":"start","nodes":{"start":{"from":"them","text":"My child I am in trouble. Please don’t call, I cannot talk right now.","choices":[{"label":"What happened?","next":"accident"},{"label":"I am calling you on the home number","next":"safe"}]},"accident":{"from":"them","text":"Car accident near Okahandja. Hospital wants N$3,500 now. Send to this MTC Money number.","choices":[{"label":"Send the money","next":"paid"},{"label":"Call the number I already have for Mom","next":"safe"}]},"paid":{"from":"system","text":"After you pay, a second emergency appears. The story expands until the money stops.","end":true},"safe":{"from":"system","text":"A live call to a known number collapses most family-emergency scams in seconds.","end":true}}}}},
     "options":[
      {"option_key":"A","is_correct":false,"content":{"en":"Send the money because it is an emergency and they asked you not to call."},"feedback":{"en":{"choice":"Secrecy plus urgency is the script.","explanation":"Real family emergencies can survive a phone call to a known number."}}},
      {"option_key":"B","is_correct":true,"content":{"en":"Call or visit using a number or address you already trust before sending anything."},"feedback":{"en":{"choice":"You verified the person, not the chat.","explanation":"Hijacked or cloned chats forbid you from calling because a voice check would end the scam."}}},
      {"option_key":"C","is_correct":false,"content":{"en":"Send half now and the rest after a photo of the hospital."},"feedback":{"en":{"choice":"Photos are easy to fake.","explanation":"Independent voice contact is the check that matters."}}},
      {"option_key":"D","is_correct":false,"content":{"en":"Ask other relatives in the same chat whether they already paid."},"feedback":{"en":{"choice":"The attacker may be in several family chats.","explanation":"Leave the compromised thread and call people directly."}}}
    ]},
    {"slug":"whatsapp-fake-manager","risk_dimensions":["Authority","Impersonation"],"content":{"en":{"title":"An impersonated manager","scenario":"A director asks for a quiet payment on WhatsApp.","channel":"WhatsApp","interaction":"whatsapp","chat":{"displayName":"Director K. Shipanga","number":"+264 81 900 1111","verified":false,"start":"start","nodes":{"start":{"from":"them","text":"Are you at your desk? I need a confidential supplier payment in the next 20 minutes. Do not mention this in email.","choices":[{"label":"Send me the bank details here","next":"details"},{"label":"I will confirm on the office landline","next":"safe"}]},"details":{"from":"them","text":"Good. New account, First National, name changed this morning. Keep this between us.","end":true},"safe":{"from":"system","text":"Managers who are really in a meeting still accept a call-back on a known number.","end":true}}}}},
     "options":[
      {"option_key":"A","is_correct":false,"content":{"en":"Process the payment because a director can override policy."},"feedback":{"en":{"choice":"Authority is being used to skip controls.","explanation":"Payment changes need the normal approval path, not a WhatsApp chat."}}},
      {"option_key":"B","is_correct":true,"content":{"en":"Do not pay. Call the manager on a known number and follow the official payment process."},"feedback":{"en":{"choice":"You kept the control in place.","explanation":"Impersonated executives demand secrecy because verification would expose them."}}},
      {"option_key":"C","is_correct":false,"content":{"en":"Ask for an email from their work address in the same chat."},"feedback":{"en":{"choice":"A compromised mailbox can send that email.","explanation":"Use a channel already on file, outside this conversation."}}},
      {"option_key":"D","is_correct":false,"content":{"en":"Make a small test payment."},"feedback":{"en":{"choice":"Test payments still leave the organisation.","explanation":"Do not change or test bank details from chat."}}}
    ]},
    {"slug":"whatsapp-giveaway-investment","risk_dimensions":["Giveaway","Investment scam"],"content":{"en":{"title":"A fake giveaway and investment pitch","scenario":"A social page promises returns in a WhatsApp group.","channel":"WhatsApp","interaction":"whatsapp","chat":{"displayName":"Namibia Crypto Yields","number":"+264 85 010 1010","start":"start","nodes":{"start":{"from":"them","text":"You were selected for a N$5,000 MTC giveaway. Join the investment desk to release it. 30% per week.","choices":[{"label":"Ask how to receive the prize","next":"deposit"},{"label":"Leave and report the account","next":"safe"}]},"deposit":{"from":"them","text":"Send N$800 in airtime first to verify you are human. Then the prize unlocks.","end":true},"safe":{"from":"system","text":"Unsolicited giveaways that require a deposit are fraud, even when they use local brand names.","end":true}}}}},
     "options":[
      {"option_key":"A","is_correct":false,"content":{"en":"Pay the small verification fee to release the prize."},"feedback":{"en":{"choice":"The prize is the lure; the fee is the theft.","explanation":"Legitimate giveaways do not ask you to send airtime to a chat."}}},
      {"option_key":"B","is_correct":true,"content":{"en":"Leave the chat, do not pay, and report the account to the platform."},"feedback":{"en":{"choice":"You refused the deposit trap.","explanation":"High weekly returns and brand-name prizes are mass social-media fraud."}}},
      {"option_key":"C","is_correct":false,"content":{"en":"Invest a tiny amount to see if the first return arrives."},"feedback":{"en":{"choice":"Early returns are paid from later victims.","explanation":"Do not test investment chats with real money."}}},
      {"option_key":"D","is_correct":false,"content":{"en":"Share the group with coworkers so they can also benefit."},"feedback":{"en":{"choice":"That recruits more victims.","explanation":"Report it rather than amplifying it."}}}
    ]},
    {"slug":"whatsapp-romance-marketplace","risk_dimensions":["Romance scam","Marketplace fraud"],"content":{"en":{"title":"Romance and marketplace pressure","scenario":"A seller and a new romantic contact both want payment off-platform.","channel":"WhatsApp","interaction":"whatsapp","chat":{"displayName":"Alex (Facebook)","number":"+264 81 222 8888","start":"start","nodes":{"start":{"from":"them","text":"The bakkie is still available. Facebook fees are too high — pay me on Mixx instead and I will deliver today. Also, you seem kind. Can we talk privately?","choices":[{"label":"Pay off-platform to save the fee","next":"paid"},{"label":"Keep payment and chat on the original platform","next":"safe"}]},"paid":{"from":"system","text":"Once money leaves the platform there is no buyer protection. Romance language is there to stop you reversing the payment.","end":true},"safe":{"from":"system","text":"Platforms exist so you can report fake sellers without exposing a personal wallet.","end":true}}}}},
     "options":[
      {"option_key":"A","is_correct":true,"content":{"en":"Stay on the official marketplace, never pay by personal wallet, and do not move a sale into a private romance chat."},"feedback":{"en":{"choice":"You kept buyer protection.","explanation":"Off-platform payment plus sudden affection is a combined marketplace and romance pattern."}}},
      {"option_key":"B","is_correct":false,"content":{"en":"Pay via Mixx because delivery is today."},"feedback":{"en":{"choice":"Urgency removes the platform’s protection.","explanation":"If the seller is genuine they can complete the sale where you found them."}}},
      {"option_key":"C","is_correct":false,"content":{"en":"Send a deposit and ask for a photo of the vehicle licence."},"feedback":{"en":{"choice":"Documents are cheap to fake.","explanation":"Do not send money before a verified, on-platform transaction."}}},
      {"option_key":"D","is_correct":false,"content":{"en":"Continue the romance chat but delay payment."},"feedback":{"en":{"choice":"The relationship is being built to request money later.","explanation":"End it if the contact was created around a sale or a request for funds."}}}
    ]},
    {"slug":"whatsapp-privacy-oversharing","risk_dimensions":["Privacy","Oversharing"],"content":{"en":{"title":"Privacy settings and oversharing","scenario":"Your status photo shows your office badge and travel dates.","channel":"WhatsApp","interaction":"whatsapp","chat":{"displayName":"You","number":"Status privacy","start":"start","nodes":{"start":{"from":"system","text":"Your status is set to Everyone. A photo shows your staff badge, desk location, and a caption: flying to Cape Town Friday. A stranger then asks for the office Wi-Fi and your travel dates.","choices":[{"label":"Answer because it seems harmless","next":"share"},{"label":"Change status privacy and do not reply with details","next":"safe"}]},"share":{"from":"system","text":"Those details help someone impersonate you to reception or target your home while you travel.","end":true},"safe":{"from":"system","text":"Limit status, last seen, and profile photo to contacts. Leave badges and travel plans off public posts.","end":true}}}}},
     "options":[
      {"option_key":"A","is_correct":false,"content":{"en":"Leave privacy on Everyone so customers can reach you easily."},"feedback":{"en":{"choice":"Public status is a research tool for attackers.","explanation":"Work contact should go through official channels, not an open WhatsApp profile."}}},
      {"option_key":"B","is_correct":true,"content":{"en":"Restrict status, photo, and last seen to contacts, and stop posting badges or travel plans."},"feedback":{"en":{"choice":"You reduced the information an impersonator can harvest.","explanation":"Oversharing supplies the personal details used in spear phishing and family scams."}}},
      {"option_key":"C","is_correct":false,"content":{"en":"Post the travel dates but blur the badge."},"feedback":{"en":{"choice":"Travel dates still advertise an empty house or office.","explanation":"Keep both identity documents and schedules off public statuses."}}},
      {"option_key":"D","is_correct":false,"content":{"en":"Tell the stranger the Wi-Fi because they are already in reception."},"feedback":{"en":{"choice":"A stranger in reception is not proof of employment.","explanation":"Direct visitors through official reception processes."}}}
    ]}
  ]'::jsonb
);

select public._seed_practice_module(
  'voice-phishing-vishing',
  '{"en":"Voice Phishing and Call Centre Scams","af":"Stemuitvissing en oproepsentrum-bedrog","pt":"Vishing e burlas de call center"}'::jsonb,
  '{"en":"Practice verifying callers when voices, caller ID, and help-desk stories can all be faked.","af":"Oefen om bellers te verifieer wanneer stemme, caller ID en hulpdeskstories nagemaak kan word.","pt":"Pratique verificar quem liga quando vozes, caller ID e histórias de helpdesk podem ser falsificados."}'::jsonb,
  '{
    "en":{"whyItMatters":"A phone call creates urgency and authority in real time. AI-cloned voices and spoofed caller ID make a scripted fraudster sound like a bank, IT, a director, or government.","warningSigns":"Requests to install remote-access software, read OTPs, move money to a safe account, or stay on the line while you log in. Caller ID matching the organisation is not proof.","bestPractice":"End the call. Use a number from the card, official app, or internal directory. IT will not ask you to install unknown remote tools from a surprise call."},
    "af":{"whyItMatters":"’n Oproep skep dringendheid en gesag. AI-stemme en valse caller ID kan soos ’n bank, IT of die regering klink.","warningSigns":"Versoeke om afstandtoegang te installeer, OTP’s te lees, geld na ’n veilige rekening te skuif, of aan die lyn te bly terwyl jy aanmeld.","bestPractice":"Sit neer. Gebruik ’n nommer op jou kaart, amptelike toep of interne lys. IT vra nie onbekende afstandnutsgoed vanaf ’n verrassingsoproep nie."},
    "pt":{"whyItMatters":"Uma chamada cria urgência e autoridade. Vozes clonadas e caller ID falso podem parecer um banco, TI ou o Estado.","warningSigns":"Pedidos para instalar acesso remoto, ler OTPs, mover dinheiro para uma conta segura ou permanecer na linha enquanto inicia sessão.","bestPractice":"Desligue. Use o número do cartão, da app oficial ou do diretório interno. TI não pede ferramentas remotas desconhecidas numa chamada surpresa."}
  }'::jsonb,
  '[
    {"slug":"vishing-ai-cloned-voice","risk_dimensions":["Deepfake audio","Family impersonation"],"content":{"en":{"title":"An AI-cloned family voice","scenario":"The voice sounds exactly like your brother. How do you verify?","channel":"Phone call","interaction":"phone","call":{"caller":"Your brother?","callerId":"+264 81 444 1212","claimedOrg":"Family","transcript":[{"speaker":"Caller","text":"It’s me. I need N$2,000 for a tow truck. Please don’t hang up, my battery is dying."},{"speaker":"You","text":"You sound upset. Where are you?"},{"speaker":"Caller","text":"Outside Windhoek. Send Mixx to this number I will text. Mom already knows."}]}}},
     "options":[
      {"option_key":"A","is_correct":false,"content":{"en":"Send the money because the voice is unmistakably your brother."},"feedback":{"en":{"choice":"Voices can be cloned from social videos.","explanation":"A short recording of someone speaking is enough for many cloning tools."}}},
      {"option_key":"B","is_correct":true,"content":{"en":"Hang up and call your brother or another family member on a number you already have. Ask a question only they can answer live."},"feedback":{"en":{"choice":"You verified the person, not the voice.","explanation":"A callback to a known number, or a family-only fact asked on a new call, defeats cloned audio."}}},
      {"option_key":"C","is_correct":false,"content":{"en":"Stay on the line and ask them to repeat a childhood nickname."},"feedback":{"en":{"choice":"Nicknames may already be in the prompt.","explanation":"End the inbound call. Any check must happen on a number you originated."}}},
      {"option_key":"D","is_correct":false,"content":{"en":"Send a smaller amount as a holding payment."},"feedback":{"en":{"choice":"Any payment rewards the clone.","explanation":"Verify first; money is hard to reverse."}}}
    ]},
    {"slug":"vishing-fake-it-support","risk_dimensions":["IT support","Remote access"],"content":{"en":{"title":"Fake IT support wants remote access","scenario":"Read the call and decide how to verify the help desk.","channel":"Phone call","interaction":"phone","call":{"caller":"IT Service Desk","callerId":"+264 61 299 0000","claimedOrg":"Company IT","transcript":[{"speaker":"Caller","text":"This is the service desk. Your machine is sending malware alerts. I need you to install AnyDesk so I can clean it."},{"speaker":"You","text":"Can I raise a ticket instead?"},{"speaker":"Caller","text":"There is no time. Read the six-digit code from your screen when the tool opens."}]}}},
     "options":[
      {"option_key":"A","is_correct":false,"content":{"en":"Install the tool because the caller ID shows the office number."},"feedback":{"en":{"choice":"Caller ID is easy to spoof.","explanation":"Real IT will have a ticket you can see in the official portal."}}},
      {"option_key":"B","is_correct":true,"content":{"en":"Hang up. Contact IT through the official portal or internal directory, and do not install remote-access software from a surprise call."},"feedback":{"en":{"choice":"You refused remote access from an inbound call.","explanation":"Remote tools plus a code give the attacker your desktop, files, and password prompts."}}},
      {"option_key":"C","is_correct":false,"content":{"en":"Install it but watch the screen the whole time."},"feedback":{"en":{"choice":"Watching does not prevent file theft.","explanation":"Once remote control is granted they can act faster than you can notice."}}},
      {"option_key":"D","is_correct":false,"content":{"en":"Give them a screenshot of the alert instead."},"feedback":{"en":{"choice":"Screenshots can leak internal data.","explanation":"Use the official ticket path with the minimum necessary detail."}}}
    ]},
    {"slug":"vishing-caller-id-spoof","risk_dimensions":["Caller ID spoofing","Banking"],"content":{"en":{"title":"Caller ID looks like the bank","scenario":"The screen says Bank Windhoek. How do you verify?","channel":"Phone call","interaction":"phone","call":{"caller":"Bank Windhoek Fraud","callerId":"Bank Windhoek","claimedOrg":"Bank Windhoek","transcript":[{"speaker":"Caller","text":"We blocked a N$18,000 payment. To reverse it I will stay on the line while you open the app and read the OTP."}]}}},
     "options":[
      {"option_key":"A","is_correct":true,"content":{"en":"Hang up and call the number printed on your card or shown in the official app."},"feedback":{"en":{"choice":"You originated the verification call.","explanation":"Spoofed caller ID can display the bank name. A number you already had is the independent check."}}},
      {"option_key":"B","is_correct":false,"content":{"en":"Stay on the line because the ID shows the bank name."},"feedback":{"en":{"choice":"Displayed names are not authenticated.","explanation":"Treat every inbound fraud call as unverified."}}},
      {"option_key":"C","is_correct":false,"content":{"en":"Read the OTP but not your PIN."},"feedback":{"en":{"choice":"The OTP is enough to approve the theft.","explanation":"Never read codes to a caller."}}},
      {"option_key":"D","is_correct":false,"content":{"en":"Ask them to call your branch and have the branch call you back."},"feedback":{"en":{"choice":"They can spoof the branch too, or keep you on a quiet hold.","explanation":"You must place a fresh call on a known number."}}}
    ]},
    {"slug":"vishing-remote-access-request","risk_dimensions":["Remote access","Fear"],"content":{"en":{"title":"A request to install remote-access software","scenario":"A Microsoft caller says your licence will be revoked.","channel":"Phone call","interaction":"phone","call":{"caller":"Microsoft Licensing","callerId":"+1 425 000 0000","claimedOrg":"Microsoft","transcript":[{"speaker":"Caller","text":"Your Windows licence is counterfeit. Download TeamViewer now or we will disable Office. I will tell you which buttons to click."}]}}},
     "options":[
      {"option_key":"A","is_correct":false,"content":{"en":"Download the tool so Office is not disabled."},"feedback":{"en":{"choice":"Fear of losing software is the lever.","explanation":"Microsoft does not cold-call to install TeamViewer."}}},
      {"option_key":"B","is_correct":true,"content":{"en":"Do not install anything. End the call and report it to IT using a known internal channel."},"feedback":{"en":{"choice":"You kept the device off a remote session.","explanation":"Unsolicited remote-access requests are a defining vishing pattern."}}},
      {"option_key":"C","is_correct":false,"content":{"en":"Check the licence key with the caller."},"feedback":{"en":{"choice":"That discloses product keys.","explanation":"Licence checks belong in official portals, not surprise calls."}}},
      {"option_key":"D","is_correct":false,"content":{"en":"Let them control the machine but revoke access afterwards."},"feedback":{"en":{"choice":"Damage can be done during the session.","explanation":"Do not grant the session at all."}}}
    ]},
    {"slug":"vishing-fake-executive","risk_dimensions":["Authority","Secrecy"],"content":{"en":{"title":"An attacker pretending to be an executive","scenario":"The CEO calls from an unknown number about a confidential transfer.","channel":"Phone call","interaction":"phone","call":{"caller":"CEO","callerId":"Private number","claimedOrg":"Your organisation","transcript":[{"speaker":"Caller","text":"I cannot take questions. Prepare a payment to a new attorney trust account before the acquisition leaks. If you verify this with anyone you will jeopardise the deal."}]}}},
     "options":[
      {"option_key":"A","is_correct":false,"content":{"en":"Process it because leaking the deal could be worse."},"feedback":{"en":{"choice":"Secrecy is how executive impersonation beats policy.","explanation":"Real deals still use documented approvals."}}},
      {"option_key":"B","is_correct":true,"content":{"en":"Do not pay. Verify through a known internal number or in person and keep the normal approval chain."},"feedback":{"en":{"choice":"You refused an unverified authority request.","explanation":"Executives who are genuine can be reached on known channels and expect controls to be followed."}}},
      {"option_key":"C","is_correct":false,"content":{"en":"Ask the caller to email the attorney letterhead."},"feedback":{"en":{"choice":"Letterheads are trivial to forge.","explanation":"Independent contact with the real executive is required."}}},
      {"option_key":"D","is_correct":false,"content":{"en":"Make the payment but add a note that it was urgent."},"feedback":{"en":{"choice":"A note does not reverse a transfer.","explanation":"Stop before money moves."}}}
    ]},
    {"slug":"vishing-government-official","risk_dimensions":["Government impersonation","Fear"],"content":{"en":{"title":"A caller claiming to be a government official","scenario":"NamRA or the police demand immediate payment.","channel":"Phone call","interaction":"phone","call":{"caller":"NamRA collections","callerId":"+264 61 209 0000","claimedOrg":"NamRA","transcript":[{"speaker":"Caller","text":"There is a warrant for unpaid tax. Pay N$7,200 in airtime or mobile money now to stop the arrest team. Do not tell anyone."}]}}},
     "options":[
      {"option_key":"A","is_correct":false,"content":{"en":"Pay because an arrest is threatened."},"feedback":{"en":{"choice":"Fear of police action is the script.","explanation":"Authorities do not collect tax in airtime over the phone."}}},
      {"option_key":"B","is_correct":true,"content":{"en":"Hang up. Contact the agency using a number from its official website or a letter you already have, and report the call."},"feedback":{"en":{"choice":"You verified independently.","explanation":"Government names and local numbers are spoofed. Use a published official contact, never the inbound call."}}},
      {"option_key":"C","is_correct":false,"content":{"en":"Ask for their employee number and stay on the line."},"feedback":{"en":{"choice":"Employee numbers can be invented.","explanation":"End the call and originate a new one."}}},
      {"option_key":"D","is_correct":false,"content":{"en":"Transfer to a family member so they can hear the official."},"feedback":{"en":{"choice":"That recruits another payer.","explanation":"Do not conference other people into an unverified demand."}}}
    ]}
  ]'::jsonb
);

select public._seed_practice_module(
  'fake-job-offers-recruitment',
  '{"en":"Fake Job Offers and Recruitment Scams","af":"Vals werksaanbiedinge en werwingsbedrog","pt":"Ofertas de emprego falsas e burlas de recrutamento"}'::jsonb,
  '{"en":"Evaluate adverts, recruiter profiles, and offer letters before you send money or documents.","af":"Evalueer advertensies, werwerprofiele en aanbodbriewe voordat jy geld of dokumente stuur.","pt":"Avalie anúncios, perfis de recrutadores e cartas de oferta antes de enviar dinheiro ou documentos."}'::jsonb,
  '{
    "en":{"whyItMatters":"Recruitment scams copy real employers. They collect fees, copies of IDs, and banking details, or they send malware as a job pack.","warningSigns":"Cloned career pages, requests for visa or training fees, paying for a laptop, interviews on random links, and email domains that are not the company’s.","bestPractice":"Find the employer through its official site, not the advert’s link. Real employers do not ask you to pay to be hired. Share documents only through verified HR processes."},
    "af":{"whyItMatters":"Werwingsbedrog boots ware werkgewers na om fooie, ID’s en bankbesonderhede te versamel.","warningSigns":"Nagebootste loopbaanblaaie, visum- of opleidingsfooie, betaling vir ’n skootrekenaar, onderhoude op vreemde skakels, en e-posdomeine wat nie die maatskappy s’n is nie.","bestPractice":"Vind die werkgewer via die amptelike webwerf. Ware werkgewers vra nie dat jy betaal om aangestel te word nie."},
    "pt":{"whyItMatters":"As burlas de recrutamento copiam empregadores reais para recolher taxas, IDs e dados bancários.","warningSigns":"Sites de carreiras clonados, taxas de visto ou formação, pagamento de portátil, entrevistas em links aleatórios e domínios de e-mail que não são da empresa.","bestPractice":"Encontre o empregador no site oficial. Empregadores reais não cobram para o contratar."}
  }'::jsonb,
  '[
    {"slug":"job-cloned-recruiter","risk_dimensions":["Cloned website","Impersonation"],"content":{"en":{"title":"A fake recruiter and cloned company site","scenario":"Inspect the advert, recruiter, and offer together.","channel":"Job offer","interaction":"job","job":{"advert":{"company":"Namdeb","title":"Remote compliance officer","salary":"N$45,000 per month","source":"WhatsApp job group","body":"Immediate start. Apply via the careers page we will send you. No interview at the mine."},"recruiter":{"name":"Leah Nangolo","title":"Talent partner","email":"leah.nangolo@namdeb-careers.example","profileNote":"The public Namdeb domain does not match namdeb-careers.example. The LinkedIn profile was created last week."},"offer":{"salary":"N$45,000","startDate":"Monday","request":"Pay N$750 to unlock the HR portal","letter":"Offer attached. Pay the onboarding portal fee today so we can issue your contract."}}}},
     "options":[
      {"option_key":"A","is_correct":false,"content":{"en":"Pay the portal fee because the salary matches local market rates."},"feedback":{"en":{"choice":"A realistic salary does not prove the employer.","explanation":"The domain is a clone. Real HR portals are reached from the official website."}}},
      {"option_key":"B","is_correct":true,"content":{"en":"Do not pay. Open the company’s official careers site yourself and contact HR through that site."},"feedback":{"en":{"choice":"You ignored the cloned domain.","explanation":"Lookalike career sites exist to collect fees and documents."}}},
      {"option_key":"C","is_correct":false,"content":{"en":"Ask the recruiter to video-call from the same email address."},"feedback":{"en":{"choice":"The cloned mailbox can still video-call.","explanation":"Verification must start from the official company site."}}},
      {"option_key":"D","is_correct":false,"content":{"en":"Send a CV only, without paying."},"feedback":{"en":{"choice":"A CV still exposes personal data to a fake recruiter.","explanation":"Confirm the vacancy exists on the official site first."}}}
    ]},
    {"slug":"job-visa-training-fee","risk_dimensions":["Advance fees","Visa fraud"],"content":{"en":{"title":"A request for visa or training fees","scenario":"An overseas role asks you to pay before the interview.","channel":"Job offer","interaction":"job","job":{"advert":{"company":"Gulf Logistics Group","title":"Warehouse supervisor, Dubai","salary":"USD 3,200","source":"Facebook ad","body":"Visa, flights, and training guaranteed. Pay the processing partner this week."},"recruiter":{"name":"Omar Saleh","title":"Overseas placements","email":"omar@gulflogistics-jobs.example","profileNote":"No company page exists under that domain. Reviews mention lost deposits."},"offer":{"salary":"USD 3,200","startDate":"On visa issue","request":"Wire USD 420 for medical and visa training","letter":"Your seat cannot be reserved until the training fee clears."}}}},
     "options":[
      {"option_key":"A","is_correct":true,"content":{"en":"Treat any request to pay for a job, visa, or training as a scam unless confirmed on the employer’s official site."},"feedback":{"en":{"choice":"You refused the advance-fee trap.","explanation":"Legitimate employers do not require you to wire money to be considered."}}},
      {"option_key":"B","is_correct":false,"content":{"en":"Pay because overseas visas always have costs."},"feedback":{"en":{"choice":"Real visa costs are paid to official authorities through verified processes.","explanation":"A recruiter’s personal account is not that process."}}},
      {"option_key":"C","is_correct":false,"content":{"en":"Send half now and the rest after the interview."},"feedback":{"en":{"choice":"Partial fees are still theft.","explanation":"Do not send money to secure an interview."}}},
      {"option_key":"D","is_correct":false,"content":{"en":"Ask a friend to pay using their account."},"feedback":{"en":{"choice":"That spreads the loss.","explanation":"Walk away and report the advert."}}}
    ]},
    {"slug":"job-equipment-payment","risk_dimensions":["Equipment scam","Remote work"],"content":{"en":{"title":"A fake remote job wants equipment money","scenario":"The offer is generous. The laptop must be bought from their supplier.","channel":"Job offer","interaction":"job","job":{"advert":{"company":"Atlantic Insights","title":"Remote data assistant","salary":"N$18,000 plus laptop","source":"Email","body":"Work from home this month. We ship equipment after you pay the courier deposit."},"recruiter":{"name":"Sandra P.","title":"People operations","email":"sandra@atlantic-insights.example","profileNote":"The website is a one-page template registered last month."},"offer":{"salary":"N$18,000","startDate":"Immediately","request":"Pay N$2,400 equipment courier insurance","letter":"Once the deposit is paid we will send a cheque for your first salary plus the deposit."}}}},
     "options":[
      {"option_key":"A","is_correct":false,"content":{"en":"Pay the deposit because they will refund it with the first salary cheque."},"feedback":{"en":{"choice":"The refund cheque is part of the scam.","explanation":"It will bounce after you have sent real money."}}},
      {"option_key":"B","is_correct":true,"content":{"en":"Do not pay for equipment. Real remote employers send devices through their own procurement, or use a known vendor invoice to the company."},"feedback":{"en":{"choice":"You refused to finance the job.","explanation":"Equipment-payment scams target people excited to start remote work."}}},
      {"option_key":"C","is_correct":false,"content":{"en":"Buy a cheaper laptop locally and expense it later."},"feedback":{"en":{"choice":"The role itself is unverified.","explanation":"Confirm the company independently before spending anything."}}},
      {"option_key":"D","is_correct":false,"content":{"en":"Give them your delivery address only."},"feedback":{"en":{"choice":"Addresses still support further targeting.","explanation":"Verify the employer first."}}}
    ]},
    {"slug":"job-identity-banking","risk_dimensions":["Identity documents","Credential theft"],"content":{"en":{"title":"Requests for ID and banking information","scenario":"HR wants certified ID, a selfie holding the ID, and a bank letter before any interview.","channel":"Job offer","interaction":"job","job":{"advert":{"company":"First Capital Namibia","title":"Graduate intern","salary":"Stipend","source":"Instagram DM","body":"Shortlisted. Upload documents in the next hour."},"recruiter":{"name":"Talent Bot","title":"Hiring assistant","email":"hr@firstcapital-jobs.example","profileNote":"The official bank careers page does not list this internship."},"offer":{"salary":"Stipend","startDate":"This week","request":"Certified ID, selfie with ID, proof of bank account, and PIN to verify the stipend","letter":"Finance cannot load your profile without a full copy of your banking PIN."}}}},
     "options":[
      {"option_key":"A","is_correct":false,"content":{"en":"Send everything quickly so you are not dropped from the shortlist."},"feedback":{"en":{"choice":"A PIN is never needed to hire you.","explanation":"ID plus banking details is enough for impersonation and account opening."}}},
      {"option_key":"B","is_correct":true,"content":{"en":"Do not send ID, selfies, or banking secrets. Confirm the vacancy on the official careers page and use only that process."},"feedback":{"en":{"choice":"You protected identity documents.","explanation":"If the job is real, HR will collect documents after a verified process, never a PIN."}}},
      {"option_key":"C","is_correct":false,"content":{"en":"Send the ID but not the PIN."},"feedback":{"en":{"choice":"The ID still enables impersonation.","explanation":"Confirm the employer first; then use their official portal."}}},
      {"option_key":"D","is_correct":false,"content":{"en":"Watermark the ID and send it on WhatsApp."},"feedback":{"en":{"choice":"Watermarks are not a substitute for a verified employer.","explanation":"Do not send identity packs into an unverified chat."}}}
    ]},
    {"slug":"job-malicious-interview-link","risk_dimensions":["Malicious links","Attachments"],"content":{"en":{"title":"A fake interview link and job attachment","scenario":"The calendar invite and the job pack both look official.","channel":"Job offer","interaction":"job","job":{"advert":{"company":"Standard Bank","title":"Analyst interview","salary":"Market related","source":"Email","body":"Join the interview on this video link and open the case-study attachment."},"recruiter":{"name":"Campus hiring","title":"Graduate recruitment","email":"careers@standardbank-interview.example","profileNote":"The real careers domain is not standardbank-interview.example."},"offer":{"salary":"Market related","startDate":"Interview Friday","request":"Open CaseStudy.iso and allow macros","letter":"If the file is blank, enable content. Use the video link even if the browser warns about the certificate."}}}},
     "options":[
      {"option_key":"A","is_correct":true,"content":{"en":"Do not open the file or the link. Confirm the interview through the official careers site or a known HR number."},"feedback":{"en":{"choice":"You treated the pack as untrusted.","explanation":"Malicious interview files and lookalike meeting links are a common recruitment payload."}}},
      {"option_key":"B","is_correct":false,"content":{"en":"Enable macros so you can prepare the case study."},"feedback":{"en":{"choice":"The blank file is the lure.","explanation":"Do not enable content in unexpected job attachments."}}},
      {"option_key":"C","is_correct":false,"content":{"en":"Click through the browser certificate warning."},"feedback":{"en":{"choice":"Certificate warnings protect you from lookalike sites.","explanation":"Stop and use the official meeting process."}}},
      {"option_key":"D","is_correct":false,"content":{"en":"Forward the pack to a friend who is also applying."},"feedback":{"en":{"choice":"That spreads the malware.","explanation":"Report it instead."}}}
    ]},
    {"slug":"job-evaluate-opportunity","risk_dimensions":["Verification","Offer review"],"content":{"en":{"title":"Is this opportunity legitimate?","scenario":"Use the advert, profile, and letter together before you decide.","channel":"Job offer","interaction":"job","job":{"advert":{"company":"Telecom Namibia","title":"Customer support lead","salary":"N$22,000 plus bonus","source":"PDF sent by WhatsApp","body":"Start tomorrow. Bring certified copies and N$300 for your staff card."},"recruiter":{"name":"HR Desk","title":"People","email":"jobs@telecomnamibia-hr.example","profileNote":"Official careers are on the company website, not a WhatsApp PDF."},"offer":{"salary":"N$22,000","startDate":"Tomorrow","request":"Staff-card cash and certified documents today","letter":"Sign the offer and pay the card fee to confirm attendance."}}}},
     "options":[
      {"option_key":"A","is_correct":false,"content":{"en":"Attend tomorrow with the cash and documents because the salary is realistic."},"feedback":{"en":{"choice":"Cash for a staff card is an advance fee.","explanation":"Legitimate onboarding does not collect cash over WhatsApp."}}},
      {"option_key":"B","is_correct":true,"content":{"en":"Treat it as illegitimate until it appears on the official careers site and HR confirms through a known channel."},"feedback":{"en":{"choice":"You required an official source.","explanation":"Adverts, recruiter mailboxes, and offer letters must all match the real employer domain and process."}}},
      {"option_key":"C","is_correct":false,"content":{"en":"Search the recruiter’s name on Facebook and proceed if a profile exists."},"feedback":{"en":{"choice":"A social profile is easy to fake.","explanation":"Use the employer’s official site as the source of truth."}}},
      {"option_key":"D","is_correct":false,"content":{"en":"Pay the N$300 because it is refundable on day one."},"feedback":{"en":{"choice":"Refund promises keep the fee moving.","explanation":"Do not pay to confirm a job."}}}
    ]}
  ]'::jsonb
);

select public._seed_practice_module(
  'mobile-money-eft-fraud',
  '{"en":"Mobile Money and EFT Fraud","af":"Selfoon-geld en EFT-bedrog","pt":"Fraude de dinheiro móvel e EFT"}'::jsonb,
  '{"en":"Verify payment redirection, changed supplier bank details, and mobile-money pressure before money leaves.","af":"Bevestig betalingsherleiding, veranderde verskafferbankbesonderhede en selfoon-gelddruk voordat geld vertrek.","pt":"Confirme o redirecionamento de pagamentos, novos dados bancários de fornecedores e pressão de carteiras móveis antes de enviar dinheiro."}'::jsonb,
  '{
    "en":{"whyItMatters":"Once an EFT or mobile-money transfer leaves, it is difficult to reverse. Attackers change invoices, spoof finance contacts, and create fake overpayments.","warningSigns":"New bank details, a different wallet number, pressure to pay immediately, requests for your PIN, and a supplier who cannot be reached on the old number.","bestPractice":"Call the supplier or colleague using a number already on file. Dual-control payments. Never update banking details from the same message that asks you to pay."},
    "af":{"whyItMatters":"Sodra ’n EFT of selfoon-oordrag weg is, is dit moeilik om terug te draai.","warningSigns":"Nuwe bankbesonderhede, ’n ander beursienommer, druk om dadelik te betaal, PIN-versoeke, en ’n verskaffer wat nie op die ou nommer bereikbaar is nie.","bestPractice":"Bel die verskaffer op ’n nommer wat al op lêer is. Gebruik dubbele beheer. Moet nooit bankbesonderhede uit dieselfde boodskap opdateer wat om betaling vra nie."},
    "pt":{"whyItMatters":"Quando um EFT ou transferência móvel sai, é difícil revertê-la.","warningSigns":"Novos dados bancários, outro número de carteira, pressão para pagar já, pedidos de PIN e um fornecedor incontactável no número antigo.","bestPractice":"Ligue ao fornecedor para um número já arquivado. Use duplo controlo. Nunca atualize dados bancários a partir da mesma mensagem que pede o pagamento."}
  }'::jsonb,
  '[
    {"slug":"mobile-payment-redirection","risk_dimensions":["Payment redirection","Urgency"],"content":{"en":{"title":"A last-minute payment redirection","scenario":"Inspect the invoice change before you release funds.","channel":"EFT","interaction":"payment","payment":{"vendor":"Coastal Fuels Namibia","invoiceNumber":"CF-10492","amount":"N$86,400.00","previousBank":"Bank Windhoek 8001234567 (Coastal Fuels Namibia)","newBank":"FNB 6221988001 (C Fuels Ops)","notice":"Accounts: Use the new FNB account from today. The Windhoek account is frozen for an audit. Pay before 15:00 or delivery stops."}}},
     "options":[
      {"option_key":"A","is_correct":false,"content":{"en":"Pay the new account so fuel delivery is not delayed."},"feedback":{"en":{"choice":"The delivery threat is there to stop a call-back.","explanation":"Redirection only becomes safe after independent verification."}}},
      {"option_key":"B","is_correct":true,"content":{"en":"Hold the payment. Call the supplier on the number already in your vendor file, not the number on this notice."},"feedback":{"en":{"choice":"You verified the change off-channel.","explanation":"Payment redirection works when finance uses the new details in the same message that demanded speed."}}},
      {"option_key":"C","is_correct":false,"content":{"en":"Split the amount across both accounts."},"feedback":{"en":{"choice":"Half the funds can still disappear.","explanation":"Do not pay either destination until the vendor confirms on a known number."}}},
      {"option_key":"D","is_correct":false,"content":{"en":"Reply to the email asking if the audit is real."},"feedback":{"en":{"choice":"The compromised mailbox will say yes.","explanation":"Use a phone number or portal already on file."}}}
    ]},
    {"slug":"mobile-changed-supplier-bank","risk_dimensions":["Changed bank details","Verification"],"content":{"en":{"title":"Changed supplier bank details","scenario":"A regular vendor sends new banking on a PDF letterhead.","channel":"EFT","interaction":"payment","payment":{"vendor":"Namibia Office Supplies","invoiceNumber":"NOS-7781","amount":"N$12,960.00","previousBank":"Standard Bank 2468101214 (Namibia Office Supplies)","newBank":"Nedbank 1199004455 (N Office Supp Pty)","notice":"Please update master data. Our accountant is on leave so reply only to this email."}}},
     "options":[
      {"option_key":"A","is_correct":true,"content":{"en":"Do not update master data from this email. Confirm with a known contact using details already on the vendor record."},"feedback":{"en":{"choice":"You protected the vendor master file.","explanation":"Letterheads are copied. Dual control and a known contact are the control that stops redirected EFTs."}}},
      {"option_key":"B","is_correct":false,"content":{"en":"Update the record because the company name is almost the same."},"feedback":{"en":{"choice":"Near-matching account names are a warning.","explanation":"Attackers register lookalike beneficiary names."}}},
      {"option_key":"C","is_correct":false,"content":{"en":"Ask them to stamp the PDF and resend."},"feedback":{"en":{"choice":"Stamps are easy to add.","explanation":"Voice or in-person confirmation on a known number is required."}}},
      {"option_key":"D","is_correct":false,"content":{"en":"Pay a N$50 test EFT to the new account."},"feedback":{"en":{"choice":"A test still confirms a criminal account.","explanation":"Do not send value until verification is complete."}}}
    ]},
    {"slug":"mobile-cash-send-reversal","risk_dimensions":["Mobile money","Reversal scam"],"content":{"en":{"title":"A fake cash-send reversal","scenario":"Someone says they sent money to you by mistake.","channel":"Mobile money","interaction":"sms","sms":{"contact":"MTC Mixx","number":"+264 81 321 0000","messages":[{"from":"them","text":"Mixx: You received N$3,500 from A. Shilongo.","time":"13:10"},{"from":"them","text":"Hi I sent that by mistake. Reverse it to this number now or I will report you for theft.","time":"13:11","flagged":true}]}}},
     "options":[
      {"option_key":"A","is_correct":false,"content":{"en":"Reverse the funds immediately so you are not reported."},"feedback":{"en":{"choice":"The fear of being accused is the lever.","explanation":"The first credit may be fake or later reversed by the operator, leaving you to fund the second payment."}}},
      {"option_key":"B","is_correct":true,"content":{"en":"Do not send money back. Check the official Mixx app or wallet history and contact the operator through its official channel."},"feedback":{"en":{"choice":"You used the official wallet, not the SMS.","explanation":"Mistaken payments are unwound by the operator, not by you sending cash to a new number."}}},
      {"option_key":"C","is_correct":false,"content":{"en":"Send half as a gesture of goodwill."},"feedback":{"en":{"choice":"Any send is a loss.","explanation":"Wait for the official transaction record."}}},
      {"option_key":"D","is_correct":false,"content":{"en":"Give them your Mixx PIN so they can reverse it themselves."},"feedback":{"en":{"choice":"The PIN is full wallet control.","explanation":"Never share mobile-money PINs."}}}
    ]},
    {"slug":"mobile-pin-request","risk_dimensions":["PIN theft","Help-desk impersonation"],"content":{"en":{"title":"A request for your mobile-money PIN","scenario":"Support wants the PIN to unlock a blocked wallet.","channel":"Mobile money","interaction":"sms","sms":{"contact":"eWallet Support","number":"140","messages":[{"from":"them","text":"Your wallet is locked after three tries. Reply with your PIN to restore it within 10 minutes.","time":"18:44","flagged":true}]}}},
     "options":[
      {"option_key":"A","is_correct":false,"content":{"en":"Reply with the PIN so the wallet is restored."},"feedback":{"en":{"choice":"Support will never ask for a PIN by SMS.","explanation":"Anyone with the PIN can empty the wallet."}}},
      {"option_key":"B","is_correct":true,"content":{"en":"Do not share the PIN. Open the official app or call the operator using a number from its website or till receipt."},"feedback":{"en":{"choice":"You kept the PIN private.","explanation":"Wallet unlocks happen inside the official app, not by texting secrets."}}},
      {"option_key":"C","is_correct":false,"content":{"en":"Send the PIN with one digit changed."},"feedback":{"en":{"choice":"That still discloses most of the secret.","explanation":"Send nothing."}}},
      {"option_key":"D","is_correct":false,"content":{"en":"Call the number that sent the SMS."},"feedback":{"en":{"choice":"The inbound number is the attacker.","explanation":"Use a published official number."}}}
    ]},
    {"slug":"mobile-overpayment-eft","risk_dimensions":["Overpayment","Cheque fraud"],"content":{"en":{"title":"A fake EFT overpayment","scenario":"A buyer overpays and wants the extra sent to a logistics partner.","channel":"EFT","interaction":"payment","payment":{"vendor":"New customer — Kalahari Retail","invoiceNumber":"INV-2201","amount":"You invoiced N$9,500. They paid N$19,000.","previousBank":"Your business account (expected N$9,500)","newBank":"Return the extra N$9,500 to FNB 6001122334 (Desert Freight)","notice":"Our accounts clerk used the wrong invoice. Refund the surplus today so the container can be released."}}},
     "options":[
      {"option_key":"A","is_correct":false,"content":{"en":"Refund the extra immediately so the shipment is not delayed."},"feedback":{"en":{"choice":"The surplus often never clears.","explanation":"You would be sending real money against a payment that is later reversed."}}},
      {"option_key":"B","is_correct":true,"content":{"en":"Do not refund. Wait until your bank confirms the original payment has fully cleared, and verify the customer independently."},"feedback":{"en":{"choice":"You did not send money against an uncleared credit.","explanation":"Overpayment scams rely on you refunding before the fake inbound EFT bounces."}}},
      {"option_key":"C","is_correct":false,"content":{"en":"Refund in airtime instead of EFT."},"feedback":{"en":{"choice":"The value still leaves.","explanation":"Do not send any surplus until clearance is confirmed."}}},
      {"option_key":"D","is_correct":false,"content":{"en":"Keep the extra as a deposit without telling them."},"feedback":{"en":{"choice":"Silence does not verify the payment.","explanation":"Speak to your bank first; do not spend or return uncleared funds."}}}
    ]},
    {"slug":"mobile-debit-order-change","risk_dimensions":["Debit order","Account takeover"],"content":{"en":{"title":"An unexpected debit-order change","scenario":"SMS says your insurance debit moved to a new account.","channel":"Mobile money","interaction":"sms","sms":{"contact":"Metropolitan","number":"+264 61 000 1234","messages":[{"from":"them","text":"METROPOLITAN: Your debit order failed. Update banking here to avoid policy lapse: https://metro-debit.example","time":"07:30","flagged":true}]}}},
     "options":[
      {"option_key":"A","is_correct":false,"content":{"en":"Open the link and enter your banking details so cover does not lapse."},"feedback":{"en":{"choice":"The lapse warning is the pressure.","explanation":"Debit-order changes must happen in the official app or a branch, not an SMS page."}}},
      {"option_key":"B","is_correct":true,"content":{"en":"Ignore the link. Open the insurer’s official app or call the number on your policy document."},"feedback":{"en":{"choice":"You used the policy’s own channel.","explanation":"Lookalike debit-order pages capture bank details for unauthorised withdrawals."}}},
      {"option_key":"C","is_correct":false,"content":{"en":"Send a proof of payment instead of banking details."},"feedback":{"en":{"choice":"That still engages a fake process.","explanation":"Start from the official policy portal."}}},
      {"option_key":"D","is_correct":false,"content":{"en":"Share the SMS with your broker in the same thread."},"feedback":{"en":{"choice":"The thread may include the malicious link.","explanation":"Contact the broker on a number you already have."}}}
    ]}
  ]'::jsonb
);

drop function if exists public._seed_practice_module(text, jsonb, jsonb, jsonb, jsonb);

